var i=`0235-gemista`;var o=`world-0235`;var n=`GR`;var r=`southern-europe`;var a=4;var l=82;var g={en:`Gemista`,ua:`Геміста`};var s={en:`A traditional Greece dish made with ground beef, white rice, yellow onion, parsley. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: яловичий фарш, білий рис, жовта цибуля, петрушка. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ground-beef`,360,`g`],[`white-rice`,170,`g`],[`yellow-onion`,150,`g`],[`parsley`,20,`g`],[`tomato`,180,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Hollow or prepare the vegetables, then fill with the prepared mixture without packing too tightly.`,ua:`Підготуйте овочі, за потреби вийміть серцевину, і наповніть начинкою, не утрамбовуючи надто щільно.`,t:[`stuffing-vegetables`],m:12,i:[[`tomato`,500,`g`],[`green-bell-pepper`,400,`g`]]},{en:`Roast in a preheated 190°C oven for about 58 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 58 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:58,i:[[`potato`,360,`g`],[`water`,250,`ml`],[`extra-virgin-olive-oil`,30,`ml`]]}];var h={slug:i,id:o,country:`GR`,region:r,servings:4,minutes:82,title:g,text:s,steps:u};export{n as country,h as default,o as id,l as minutes,r as region,a as servings,i as slug,u as steps,s as text,g as title};